A = [[2,1,1],[4,3,3],[8,7,9]]
b = [4,10,24]
n = 3
L = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
U = [row[:] for row in A]
for k in range(n):
    for i in range(k + 1, n):
        m = U[i][k] / U[k][k]
        L[i][k] = m
        for j in range(k, n):
            U[i][j] -= m * U[k][j]
y = [0.0] * n
for i in range(n):
    s = b[i]
    for j in range(i):
        s -= L[i][j] * y[j]
    y[i] = s / L[i][i]
x = [0.0] * n
for i in range(n - 1, -1, -1):
    s = y[i]
    for j in range(i + 1, n):
        s -= U[i][j] * x[j]
    x[i] = s / U[i][i]
for v in x:
    print(int(round(v)))
